package com.v2ray.md.ui.compose

import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Matrix
import androidx.compose.ui.graphics.Outline
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.Shape
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.Density
import androidx.compose.ui.unit.LayoutDirection
import kotlin.math.cos
import kotlin.math.sin

class SunnyShape(
    private val points: Int = 10,
    private val depth: Float = 0.08f
) : Shape {
    override fun createOutline(
        size: Size,
        layoutDirection: LayoutDirection,
        density: Density
    ): Outline {
        val path = Path()
        val centerX = size.width / 2f
        val centerY = size.height / 2f
        val radius = minOf(centerX, centerY)
        val innerRadius = radius * (1f - depth)

        var angle = -Math.PI / 2.0 // Start at top
        val angleIncrement = Math.PI / points

        path.moveTo(
            x = centerX + (radius * cos(angle)).toFloat(),
            y = centerY + (radius * sin(angle)).toFloat()
        )

        for (i in 1..(points * 2)) {
            angle += angleIncrement
            val currentRadius = if (i % 2 == 0) radius else innerRadius
            path.lineTo(
                x = centerX + (currentRadius * cos(angle)).toFloat(),
                y = centerY + (currentRadius * sin(angle)).toFloat()
            )
        }
        path.close()
        return Outline.Generic(path)
    }
}

/**
 * Shape from an exact SVG geometry (144 box): scales the baked path to fit.
 * Used for the user-supplied very-sunny / 12-sided-cookie artwork.
 */
class ScaledSvgShape(
    private val pathData: String,
    private val viewBox: Float = 144f
) : Shape {
    override fun createOutline(
        size: Size,
        layoutDirection: LayoutDirection,
        density: Density
    ): Outline {
        val path = PathParser().parsePathString(pathData).toPath()
        val s = minOf(size.width, size.height) / viewBox
        path.transform(
            Matrix().apply {
                this[0, 0] = s
                this[1, 1] = s
                this[0, 3] = (size.width - viewBox * s) / 2f
                this[1, 3] = (size.height - viewBox * s) / 2f
            }
        )
        return Outline.Generic(path)
    }
}

